import {encodeAbiParameters, keccak256, solidityPacked} from "src/ethereUtils";
import {Bundler} from "src/Bundler";
import {ENTRYPOINT_V7, ENTRYPOINT_V8} from "src/constants";
import type {Transport} from "src/transport";
import type {StateOverrideSet, UserOperationV7, UserOperationV8} from "../types";
import {Paymaster} from "./Paymaster";

/**
 * A paymaster that sponsors UserOperations for accounts verified through
 * World ID proof-of-personhood. Encodes the World ID Merkle root,
 * nullifier hash, and zero-knowledge proof into the paymasterData field
 * and re-estimates gas limits via the bundler.
 */
export class WorldIdPermissionlessPaymaster extends Paymaster {
	/** The on-chain paymaster contract address. */
	readonly address: string;

	/**
	 * @param address - The deployed WorldIdPermissionlessPaymaster contract address
	 */
	constructor(address: string) {
		super();
		this.address = address;
	}

	/**
	 * createPaymasterUserOperation will estimate gas and set the paymaster fields.
	 * @param userOperation - User operation to be sponsored. Its
	 * verificationGasLimit and callGasLimit are trusted as prior estimates
	 * (e.g. from createUserOperation) and reused during re-estimation;
	 * only preVerificationGas is always re-estimated.
	 * @param bundlerRpc - Bundler endpoint rpc url
	 * @param nullifierHash - nullifier hash
	 * @param root - Worldid Merkle tree root
	 * @param proof - Worldid zk proof
	 * @param overrides - Overrides for the default values
	 * @returns a promise of UserOperationV8 | UserOperationV7
	 */
	async createPaymasterUserOperation(
		userOperation: UserOperationV8,
		bundlerRpc: string | Transport | Bundler,
		nullifierHash: bigint,
		root: bigint,
		proof: string,
		overrides?: {
			/** set the entrypoint address instead of determining it from the useroperation structure. */
			entrypoint?: string;

			/** pass some state overrides for gas estimation */
			state_override_set?: StateOverrideSet;
		},
	): Promise<UserOperationV8>;
	async createPaymasterUserOperation(
		userOperation: UserOperationV7,
		bundlerRpc: string | Transport | Bundler,
		nullifierHash: bigint,
		root: bigint,
		proof: string,
		overrides?: {
			/** set the entrypoint address instead of determining it from the useroperation structure. */
			entrypoint?: string;

			/** pass some state overrides for gas estimation */
			state_override_set?: StateOverrideSet;
		},
	): Promise<UserOperationV7>;
	async createPaymasterUserOperation(
		userOperation: UserOperationV8 | UserOperationV7,
		bundlerRpc: string | Transport | Bundler,
		nullifierHash: bigint,
		root: bigint,
		proof: string,
		overrides?: {
			/** set the entrypoint address instead of determining it from the useroperation structure. */
			entrypoint?: string;
			/** pass some state overrides for gas estimation */
			state_override_set?: StateOverrideSet;
		},
	): Promise<UserOperationV8 | UserOperationV7> {
		//256 bytes for proof
		if (proof.slice(0, 2) !== "0x" || proof.length !== 514) {
			throw new RangeError("Invalid proof.");
		}

		proof = proof.slice(2);
		const proofArr = [
			`0x${proof.slice(0, 64)}`,
			`0x${proof.slice(64, 128)}`,
			`0x${proof.slice(128, 192)}`,
			`0x${proof.slice(192, 256)}`,
			`0x${proof.slice(256, 320)}`,
			`0x${proof.slice(320, 384)}`,
			`0x${proof.slice(384, 448)}`,
			`0x${proof.slice(448, 512)}`,
		];

		const paymasterData =
			encodeAbiParameters(["uint256"], [root]) +
			encodeAbiParameters(["uint256"], [nullifierHash]).slice(2) +
			encodeAbiParameters(["uint256[8]"], [proofArr]).slice(2);

		// work on a shallow copy so the caller's userOperation is not mutated
		// (and not left corrupted if estimation throws below)
		const userOp: UserOperationV8 | UserOperationV7 = { ...userOperation };
		userOp.paymaster = this.address;
		userOp.paymasterData = paymasterData;
		userOp.paymasterPostOpGasLimit = 45_000n;
		userOp.paymasterVerificationGasLimit = 350_000n;

		if (overrides == null) {
			overrides = {};
		}
		let entrypointAddress = overrides.entrypoint;

		if (entrypointAddress == null) {
			if ("eip7702Auth" in userOp) {
				entrypointAddress = ENTRYPOINT_V8;
			} else {
				entrypointAddress = ENTRYPOINT_V7;
			}
		}

		let preVerificationGas = userOp.preVerificationGas;
		let verificationGasLimit = userOp.verificationGasLimit;
		let callGasLimit = userOp.callGasLimit;

		// Zero only preVerificationGas: the paymaster fields added above grow
		// the calldata, so pvg must be re-estimated. verificationGasLimit and
		// callGasLimit are paymaster-independent on v0.7+ (paymaster
		// validation has its own gas field), so the supplied values are
		// trusted as prior estimates and passed through — bundlers that skip
		// estimating supplied fields answer faster. This assumes the caller's
		// op carries real estimates (e.g. from createUserOperation).
		userOp.preVerificationGas = 0n;

		const bundler = Bundler.from(bundlerRpc);
		const estimation = await bundler.estimateUserOperationGas(
			userOp,
			entrypointAddress as string,
			overrides.state_override_set,
		);

		// only change gas limits if the estimated limits is higher than
		// the supplied
		if (preVerificationGas < estimation.preVerificationGas) {
			preVerificationGas = estimation.preVerificationGas;
		}
		if (verificationGasLimit < estimation.verificationGasLimit) {
			verificationGasLimit = estimation.verificationGasLimit;
		}
		if (callGasLimit < estimation.callGasLimit) {
			callGasLimit = estimation.callGasLimit;
		}

		userOp.preVerificationGas = preVerificationGas;
		userOp.verificationGasLimit = verificationGasLimit;
		userOp.callGasLimit = callGasLimit;

		return userOp;
	}
}

/**
 * Build the signal parameter expected by `@worldcoin/idkit`'s `IDKitWidget`.
 * Binds the proof to a specific account, nonce, and chain.
 * @param accountAddress - account address
 * @param accountNonce - account nonce
 * @param chainId - chain id
 * @returns keccak256 hash to use as the `signal` for IDKitWidget
 */
export function createWorldIdSignal(
	accountAddress: string,
	accountNonce: bigint,
	chainId: bigint,
): string {
	return keccak256(
		solidityPacked(["address", "uint256", "uint256"], [accountAddress, accountNonce, chainId]),
	);
}
